void placeOrder(Order o) {
    log.info("start placeOrder");
    security.check("ORDER_WRITE");
    long t0 = System.nanoTime();
    validate(o);
    save(o);
    metrics.record("placeOrder", System.nanoTime() - t0);
}

void cancelOrder(long id) {
    log.info("start cancelOrder");
    security.check("ORDER_WRITE");
    long t0 = System.nanoTime();
    markCancelled(id);
    metrics.record("cancelOrder", System.nanoTime() - t0);
}

